SELECT id, product_name, cost, stock_qty, launch_date, SUM(stock_qty) OVER (PARTITION BY MONTH(launch_date), category ORDER BY stock_qty, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_stock_qty, SUM(cost) OVER w_recent running_cost, LAG(price, 1) OVER (PARTITION BY brand ORDER BY stock_qty, id) prev_price, ROW_NUMBER() OVER (PARTITION BY brand ORDER BY cost, id) row_seq FROM products WINDOW w_recent AS (PARTITION BY brand ORDER BY cost, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
